import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

final class BubbleSortTest {
    private BubbleSortTest() {
    }

    public static void main(String[] args) {
        sortsValuesInPlace();
        createsSortedCopies();
        rejectsNullArrays();
        formatsArraysWithOriginalSpacing();
        printsDemoOutput();

        System.out.println("All tests passed.");
    }

    private static void sortsValuesInPlace() {
        for (SortCase sortCase : sortCases()) {
            int[] numbers = sortCase.input.clone();

            BubbleSort.sort(numbers);

            assertArrayEquals(sortCase.expected, numbers);
        }
    }

    private static void createsSortedCopies() {
        int[] numbers = {4, 2, 3};

        int[] sortedNumbers = BubbleSort.sortedCopy(numbers);

        assertArrayEquals(new int[] {2, 3, 4}, sortedNumbers);
        assertArrayEquals(new int[] {4, 2, 3}, numbers);
    }

    private static void rejectsNullArrays() {
        assertThrowsNullPointerException(new Runnable() {
            @Override
            public void run() {
                BubbleSort.sort(null);
            }
        });
        assertThrowsNullPointerException(new Runnable() {
            @Override
            public void run() {
                BubbleSort.sortedCopy(null);
            }
        });
    }

    private static void formatsArraysWithOriginalSpacing() {
        assertEquals("3 4 5 ", IntArrayFormatter.format(new int[] {3, 4, 5}));
    }

    private static void printsDemoOutput() {
        ByteArrayOutputStream output = new ByteArrayOutputStream();

        BubbleSortDemo.run(new PrintStream(output));

        String expectedOutput = "Sorted array: "
                + System.lineSeparator()
                + "11 12 22 25 34 64 90 "
                + System.lineSeparator();
        assertEquals(expectedOutput, output.toString(StandardCharsets.UTF_8));
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                    "Expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but got \"" + actual + "\"");
        }
    }

    private static void assertThrowsNullPointerException(Runnable action) {
        try {
            action.run();
        } catch (NullPointerException expected) {
            return;
        }

        throw new AssertionError("Expected NullPointerException");
    }

    private static SortCase[] sortCases() {
        return new SortCase[] {
                new SortCase(new int[] {64, 34, 25, 12, 22, 11, 90}, new int[] {11, 12, 22, 25, 34, 64, 90}),
                new SortCase(new int[] {1, 2, 3, 4}, new int[] {1, 2, 3, 4}),
                new SortCase(new int[] {5, 1, 5, 3, 1}, new int[] {1, 1, 3, 5, 5}),
                new SortCase(new int[] {}, new int[] {})
        };
    }

    private static final class SortCase {
        private final int[] input;
        private final int[] expected;

        private SortCase(int[] input, int[] expected) {
            this.input = input;
            this.expected = expected;
        }
    }
}

